async function loadAttachments(node,messageId){const actor=user?.id,generation=accountGeneration,active=()=>isAccount(actor,generation)&&node.isConnected;if(!actor)return;if(node.dataset.attachments==='loading')return;node.dataset.attachments='loading';try{const {data,error}=await db.from('chat_attachments').select('id,object_path,file_name,mime_type,byte_size').eq('message_id',messageId);if(error)throw error;if(!active())return;node.querySelectorAll('.attachment-link,.media-preview,.media-status').forEach(x=>x.remove());if(!data?.length){const p=document.createElement('span');p.className='media-status tiny muted';p.textContent='Media is uploading. Refresh if it does not appear.';node.append(p);return}for(const item of data){const a=document.createElement('a');a.className='attachment-link';a.textContent='Open '+item.file_name+' ('+(item.byte_size/1048576).toFixed(2)+' MB)';a.href='#';a.onclick=async ev=>{ev.preventDefault();await mediaUi.open({...item,message_id:messageId})};node.append(a);if(item.mime_type.startsWith('image/')&&settingsUi.shouldPreview()){const {data:signed,error}=await db.storage.from('chat-media').createSignedUrl(item.object_path,mediaLinkLifetime(node.dataset.expires));if(!error&&active()){const image=document.createElement('img');image.src=signed.signedUrl;image.alt=item.file_name;image.loading='lazy';image.className=isStickerAttachment(item)?'media-preview chat-sticker':'media-preview';if(isStickerAttachment(item)){node.classList.add('sticker-message');node.dataset.stickerName=item.file_name;const label=node.querySelector('.bubble-body');if(label)label.hidden=label.textContent===item.file_name;image.alt='Sticker: '+item.file_name.replace(/^luo-sticker-|\.(png|gif|webp)$/g,'');}node.append(image)}}}}catch(e){if(active())note('Could not load media: '+e.message)}finally{delete node.dataset.attachments}}
async function loadReplyQuote(node,id,excerpt=null){try{const {data,error}=await db.from('chat_messages').select('body,recalled_at,deleted_at,expires_at').eq('id',id).maybeSingle();if(error)throw error;if(node.isConnected)node.textContent=data&&!data.recalled_at&&!data.deleted_at&&(!data.expires_at||new Date(data.expires_at)>new Date())?(excerpt||data.body).slice(0,500):'Original message unavailable'}catch{node.textContent='Reply unavailable'}}
$('avatarFile').onchange=async()=>{const file=$('avatarFile').files[0];if(!file||!user)return;const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type];if(!ext||file.size>5242880||!file.size)return note('Choose a JPEG, PNG or WebP image up to 5 MB.');$('avatarFile').disabled=true;try{const path=user.id+'/'+opid()+'.'+ext;const {error}=await db.storage.from('avatars').upload(path,file,{contentType:file.type});if(error)throw error;const r=await db.rpc('set_my_chat_avatar',{avatar_path:path});if(r.error){await db.storage.from('avatars').remove([path]);throw r.error}profile.avatar_url=db.storage.from('avatars').getPublicUrl(path).data.publicUrl;renderAvatar();settingsUi.refreshProfile();note('Profile picture saved.')}catch(e){note(e.message)}finally{$('avatarFile').disabled=false;$('avatarFile').value=''}};
