const baseRenderMembers=renderGroupMembers;renderGroupMembers=function(){baseRenderMembers();const actor=current?.members?.find(m=>m.user_id===user?.id),owner=actor?.role==='owner',manager=owner||actor?.role==='admin';$('renameGroup').classList.toggle('hidden',!manager);$('addMember').classList.toggle('hidden',!manager);if(!owner)return;const rows=$('groupMembersList').querySelectorAll('.memberrow');(current.members||[]).forEach((m,i)=>{if(m.user_id===user.id||!rows[i])return;for(const [label,action] of [[m.role==='admin'?'Make member':'Make admin','role'],['Make owner','owner']]){const button=document.createElement('button');button.className='ghost';button.textContent=label;button.onclick=async()=>{if(!confirm(label+' for this person?'))return;if(action==='owner'){const r=await db.rpc('transfer_group_ownership',{target_conversation_id:current.id,new_owner_user_id:m.user_id});if(r.error)return note(r.error.message);await loadChats();renderGroupMembers()}else await manageGroupAction('role',{target_user_id:m.user_id,new_role:m.role==='admin'?'member':'admin'})};rows[i].append(button)}})};
