// Reconcile messages after reconnects, including updates missed while the browser slept.
let reconciling=false;
async function revalidateMessages(id,active){
 const nodes=[...$('messages').querySelectorAll('[data-message]')],quotes=[...$('messages').querySelectorAll('.reply-quote[data-reply]')];
 const ids=[...new Set([...nodes.map(n=>n.dataset.message),...quotes.map(n=>n.dataset.reply),...(replyTarget?[replyTarget.id]:[]),...(mediaUi.sourceId(id)?[mediaUi.sourceId(id)]:[])])],accessible=new Map();
 for(let i=0;i<ids.length;i+=200){const r=await db.from('chat_messages').select('id,body,expires_at').eq('conversation_id',id).in('id',ids.slice(i,i+200)).is('deleted_at',null).is('recalled_at',null);if(!active())return;if(r.error)throw r.error;for(const m of r.data||[])if(!m.expires_at||new Date(m.expires_at)>new Date())accessible.set(m.id,m)}
 if(!active())return;
 deviceCache.reconcileRoom(id,ids,[...accessible.keys()]).catch(()=>{});mediaUi.revalidate(id,accessible);for(const node of nodes)if(!accessible.has(node.dataset.message))node.remove();
 for(const quote of quotes){const m=accessible.get(quote.dataset.reply);quote.textContent=m?(quote.dataset.excerpt||m.body||'').slice(0,500):'Original message unavailable'}
 if(replyTarget&&!accessible.has(replyTarget.id)){replyTarget=null;showReply();note('The message you were replying to is no longer available.')}
}
async function reconcile(){
 if(reconciling||!user||navigator.onLine===false||document.visibilityState!=='visible'||(document.querySelector('.app').dataset.tab&&document.querySelector('.app').dataset.tab!=='chats')||(!$('home').classList.contains('active')&&!$('room').classList.contains('active')))return;const actor=user.id,generation=accountGeneration;reconciling=true;
 try{await loadChats();if(!isAccount(actor,generation))return;const id=current?.id,request=roomRequest;if(!id)return;const active=()=>isAccount(actor,generation)&&current?.id===id&&request===roomRequest;
  const r=await db.from('chat_messages').select('*').eq('conversation_id',id).order('created_at',{ascending:false}).order('id',{ascending:false}).limit(100);if(!active())return;if(r.error)throw r.error;
  if($('messages').dataset.offline==='true'){$('messages').replaceChildren();delete $('messages').dataset.offline}const nearBottom=$('messages').scrollHeight-$('messages').scrollTop-$('messages').clientHeight<100,top=$('messages').scrollTop;
  for(const m of [...(r.data||[])].reverse()){if(document.querySelector('[data-message="'+m.id+'"]'))updateMessage(m);else append(m)}
  await revalidateMessages(id,active);if(!active())return;deviceCache.saveMessages(id,[...(r.data||[])].reverse()).catch(()=>{});
  if(!nearBottom)$('messages').scrollTop=top;else await markRead(id,r.data?.[0]?.id||null);
  if(!active())return;await enhancements.refreshRoom();if(!active())return;
  for(const node of $('messages').querySelectorAll('.media-status')){const parent=node.closest('[data-message]');if(parent)loadAttachments(parent,parent.dataset.message)}
 }catch(e){if(isAccount(actor,generation))$('state').textContent=navigator.onLine?'RETRYING':'OFFLINE'}finally{if(generation===accountGeneration)reconciling=false}
}
setInterval(reconcile,15000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')reconcile()});window.addEventListener('online',reconcile);window.addEventListener('offline',()=>{$('state').textContent='OFFLINE'});
